import{_ as l,l as o,o as t,c as i,v as A,p as s,x as r,d as E,i as B,S as h,b as a}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"程序化交易管理规定与实施细则","description":"","frontmatter":{"title":"程序化交易管理规定与实施细则","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/cn-program-trading-rules.md","filePath":"quant/cn-program-trading-rules.md","lastUpdated":1789023840000}'),d={name:"quant/cn-program-trading-rules.md"};function p(c,e,u,m,f,q){const n=o("Mermaid");return t(),i("div",null,[e[1]||(e[1]=A('<h1 id="程序化交易管理规定与实施细则" tabindex="-1">程序化交易管理规定与实施细则 <a class="header-anchor" href="#程序化交易管理规定与实施细则" aria-label="Permalink to &quot;程序化交易管理规定与实施细则&quot;">​</a></h1><div class="epigraph"><p>程序化交易是指通过计算机程序自动生成或者下达交易指令在证券交易所进行证券交易的行为，相关活动应遵循公平原则，不得影响证券交易所系统安全或者扰乱正常交易秩序。</p><footer>—— 中国证监会《证券市场程序化交易管理规定（试行）》（证监会公告〔2024〕8 号），2024 年 10 月 8 日起施行</footer></div><p>程序化交易在《证券法》下已有规制基础。证监会 2024 年 5 月发布《证券市场程序化交易管理规定（试行）》（以下简称《管理规定》），把报告、监测、信息系统、高频交易与监督管理写成部门规章层级的框架，授权证券交易所细化。沪、深、北交易所 2023 年 9 月先以《关于股票程序化交易报告工作有关事项的通知》《关于加强程序化交易管理有关事项的通知》落地报告与重点监控；2025 年 4 月 3 日发布《程序化交易管理实施细则》，自 2025 年 7 月 7 日起施行，把四类异常行为、高频认定、交易单元与主机托管写成可执行条文。本篇按公开文本把约束写进交易状态机：先报告后交易、会员核查、异常行为定义、系统与应急。它不是如何把报单拆到监控指标以下，也不是如何维持未报告账户继续自动下单。衔接<a href="/quant/cn-hft-threshold">高频认定</a>、<a href="/quant/cn-fee-cancel-ratio">差异化收费</a>与<a href="/quant/cn-amac-program-trading">中基协自律</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>量化回测里的「策略」常被当成一个收益过程。规则里的程序化交易是<strong>指令生成方式</strong>：计算机自动生成或下达，包括选券选时的策略单，也包括把大单拆开的算法单。主体覆盖会员客户（私募、合格境外投资者、个人等）、会员自营与资管、使用交易单元的公募与保险机构。未报告不得交易——《管理规定》落实「先报告、后交易」。问题是把报告状态写成开仓许可：账户基本信息、资金与杠杆来源、策略类型与指令执行方式、最高申报速率与单日最高申报笔数、软件名称版本与开发主体。信息重大变更要改报。回测若对未进入报告名单的历史账户假设全程可自动下单，与现行开仓条件不一致。</p><p>第二句话是公平与系统安全，不是「量化好坏」。条文反复出现的禁区是：影响交易所系统安全、扰乱正常交易秩序、利用程序化从事内幕交易、利用未公开信息交易、操纵市场。会员必须按公平合理原则提供交易单元、主机托管、行情，不得为程序化投资者提供特殊便利。策略收益函数不在规章里；规章写的是谁必须报告、谁必须拦住异常单。</p><h3 id="报告路径是会员转报-不是策略保密协议" tabindex="-1">报告路径是会员转报，不是策略保密协议 <a class="header-anchor" href="#报告路径是会员转报-不是策略保密协议" aria-label="Permalink to &quot;报告路径是会员转报，不是策略保密协议&quot;">​</a></h3><p>客户向接受委托的会员报告，会员核查（含身份穿透、资金、交易与软件信息）后向交易所报，交易所确认后客户方可交易。会员应在收到客户报告后五个交易日内向交易所报告（实施细则口径）。合格境外投资者可与会员约定由会员代为履行报告。会员自身及使用交易单元的其他机构直接向交易所报告。收益互换等通过自身账户做程序化的，还要按交易所要求报告客户信息。拒绝报告、报告不实或拒不配合核查的，会员应按委托协议拒绝其程序化委托，并向交易所报告。这把「策略知识产权」限制在报告内容的粒度上：须报策略类型及主要内容、速率与笔数，而不是把源码交给市场；但不报就不能用程序下单。</p><p><span class="marginnote">交易所接收报告「不代表对策略可用性、安全性、合规性作出判断或者保证」。报告不是牌照，也不是免责。一致性比对会把实际报撤行为与所报速率、策略类型对照；不符可被督促、警示直至限制交易。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>工程上应把规则做成两层过滤器。第一层是资格：该账户是否已在会员侧完成程序化报告且交易所已确认；软件版本、服务器与所报是否一致；资金与杠杆是否仍在所报区间。不满足则路由到人工或拒绝自动通道，而不是降级为「手工填同一张单」。第二层是行为：实时监控《实施细则》第十八条四类重点——瞬时申报速率异常（1 秒内申报、撤单笔数达标准）、频繁瞬时撤单（多次 1 秒内报了又撤且全日撤单比例达标准）、频繁拉抬打压（全日多次个股 1 分钟涨跌与自身成交占比达标准）、短时间大额成交（主要指数 1 分钟波动与自身主动成交金额及占比达标准）。未达阈值但接近且多次同类型的，交易所仍可认定或要求会员重点监控。机构以产品维度做程序化的，不得分拆产品规避异常交易监管。</p><p>会员须把程序化纳入异常交易监控，对可能严重影响价格和流动性的指令加强审核。客户拒不履行报告、系统重大故障、实际系统与验证测试不一致、可能影响系统安全或秩序的，会员应拒绝委托或撤销申报。突发性事件（不可抗力、意外、重大技术故障、重大人为差错）可能影响交易正常进行时，投资者应立即暂停交易、撤销委托并报告；会员对客户同样有暂停与撤单义务。这是公开的应急动作，不是可选的「视 P&amp;L 再停」。</p><h3 id="四类异常是构成要件-阈值由交易所掌握" tabindex="-1">四类异常是构成要件，阈值由交易所掌握 <a class="header-anchor" href="#四类异常是构成要件-阈值由交易所掌握" aria-label="Permalink to &quot;四类异常是构成要件，阈值由交易所掌握&quot;">​</a></h3><p>条文给出的是行为画像，具体笔数、比例、金额标准由交易所监控指标另定，并可调整。2024 年 4 月起四类股票程序化异常已试运行。研究与风控应订阅现行指标，而不是把新闻里的举例数字写死进代码后不再更新。债券、基金、存托凭证参照股票标准重点监控。北向（沪股通、深股通）按内外资一致纳入报告与同一监控标准，报告经香港经纪、联交所再至沪深所。把北向当成「另一套异常定义」与公开规则不符。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>《管理规定》把程序化从「一种策略风格」改写成「一种市场进入方式」。进入要登记，存续要与登记一致，退出要变更报告。高频是子集，见<a href="/quant/cn-hft-threshold">认定标准</a>；收费与撤单是价格工具，见<a href="/quant/cn-fee-cancel-ratio">差异化收费</a>；主机托管与交易单元是基础设施公平，见<a href="/quant/cn-colocation-rectify">托管清退</a>。行业协会的检查与私募运作要求见<a href="/quant/cn-amac-program-trading">中基协</a>。对量化工程的含义是：容量与夏普必须在「已报告、未触发异常、未用特殊通道」的可行集上估。把美股或期货高频的报撤密度直接套到 A 股股票竞价，会在第一层就被会员拒单。</p><p><span class="marginnote">《管理规定》第五条要求证监会指导交易所、中金所、证券业协会、基金业协会、中证数据等建立统计监测与跨市场信息共享。单交易所回测看不到跨市场联动监控。实盘合规要按账户与产品在券商、协会、交易所三条线同时可解释。</span></p><h3 id="与交易规则、两融、t-1-的叠加" tabindex="-1">与交易规则、两融、T+1 的叠加 <a class="header-anchor" href="#与交易规则、两融、t-1-的叠加" aria-label="Permalink to &quot;与交易规则、两融、T+1 的叠加&quot;">​</a></h3><p>程序化不创造额外的回转或做空权限。股票竞价仍受<a href="/quant/cn-tplus1">T+1</a>；融券仍受<a href="/quant/cn-short-constraint">做空约束</a>与<a href="/quant/cn-margin-short-t0">融券日内回转封堵</a>。算法可以把可卖库存拆成多笔，但不能把锁定量当日卖掉。涨跌停与集合竞价仍按<a href="/quant/cn-limit-auction">交易规则</a>。程序化细则是叠加层：同样的价格与库存约束，多了报告与报撤形态约束。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>《管理规定》自 2024 年 10 月 8 日施行；交易所实施细则自 2025 年 7 月 7 日施行。历史回测必须用当时有效的通知与细则，不能用今日第十八条四类去惩罚 2019 年的报单。细则所称「以上」含本数。交易所可调整高频情形与异常标准。拆单算法若以满足大额减冲击或组合公平为目的、且已履行普通程序化报告，高频的额外报告可有例外，主体限于公募及其子公司、从事资管的会员、合格境外投资者及交易所认定的其他投资者——这是条文里的例外，不是把任何拆单都标成「不是程序化」。</p><p>不要设计分拆账户、分拆产品以摊薄秒内笔数或撤单率。不要把未报告通道、非正式系统对接当成执行备选。不要假设报告信息可用于向客户推销「已获交易所认可」。公开文本下的研究止于：报告状态、四类行为、会员拒绝权与应急停机如何进入模拟器的合法动作集。</p><p><span class="marginnote">保存期限：会员及使用交易单元的其他机构对报告信息与交易资料保存不少于二十年。这与中基协对私募程序化资料自清算起不少于二十年的要求同方向。研究日志若短于法定保存，不能作为事后合规抗辩。</span></p>',23)),(t(),s(h,null,{default:r(()=>[B(n,{id:"mermaid-67",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEF%5B%22%E8%87%AA%E5%8A%A8%E7%94%9F%E6%88%90%E6%88%96%E4%B8%8B%E8%BE%BE%E6%8C%87%E4%BB%A4%22%5D%20--%3E%20RPT%5B%22%E5%90%91%E4%BC%9A%E5%91%98%20%2F%20%E4%BA%A4%E6%98%93%E6%89%80%E6%8A%A5%E5%91%8A%22%5D%0A%20%20RPT%20--%3E%20CHK%5B%22%E4%BC%9A%E5%91%98%E6%A0%B8%E6%9F%A5%E4%B8%8E%E7%A9%BF%E9%80%8F%22%5D%0A%20%20CHK%20--%3E%20EX%5B%22%E4%BA%A4%E6%98%93%E6%89%80%E6%8E%A5%E6%94%B6%E7%A1%AE%E8%AE%A4%22%5D%0A%20%20EX%20--%3E%20OK%5B%22%E5%85%81%E8%AE%B8%E7%A8%8B%E5%BA%8F%E5%8C%96%E4%BA%A4%E6%98%93%22%5D%0A%20%20OK%20--%3E%20MON%5B%22%E5%AE%9E%E6%97%B6%E7%9B%91%E6%8E%A7%E5%9B%9B%E7%B1%BB%E5%BC%82%E5%B8%B8%22%5D%0A%20%20MON%20--%3E%7C%22%E8%A7%A6%E5%8F%91%E6%88%96%E6%8E%A5%E8%BF%91%E4%B8%94%E5%A4%9A%E6%AC%A1%22%7C%20ACT%5B%22%E8%AD%A6%E7%A4%BA%20%2F%20%E9%99%90%E5%88%B6%E4%BA%A4%E6%98%93%20%2F%20%E4%BC%9A%E5%91%98%E6%8B%92%E5%8D%95%22%5D%0A%20%20NO%5B%22%E6%9C%AA%E6%8A%A5%E5%91%8A%E6%88%96%E4%B8%8D%E5%AE%9E%22%5D%20--%3E%20BAN%5B%22%E4%B8%8D%E5%BE%97%E7%A8%8B%E5%BA%8F%E5%8C%96%E4%B8%8B%E5%8D%95%22%5D%0A%20%20EVT%5B%22%E7%AA%81%E5%8F%91%E6%95%85%E9%9A%9C%E6%88%96%E4%BA%BA%E4%B8%BA%E5%B7%AE%E9%94%99%22%5D%20--%3E%20HALT%5B%22%E6%9A%82%E5%81%9C%E4%BA%A4%E6%98%93%E5%B9%B6%E6%92%A4%E5%8D%95%E6%8A%A5%E5%91%8A%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[E(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a("h2",{id:"小结",tabindex:"-1"},[E("小结 "),a("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),e[3]||(e[3]=a("ul",null,[a("li",null,"程序化交易以指令自动化定义，须先报告后交易，信息变更要改报。"),a("li",null,"《管理规定》提供框架，沪深北《实施细则》给出四类异常、高频、系统与托管的可执行条文。"),a("li",null,"会员对客户有核查、拒单、撤单与应急义务；分拆产品规避监控被明确禁止。"),a("li",null,"北向按内外资一致适用报告与监控标准。"),a("li",null,"回测必须嵌入报告资格与当时有效的监控指标，而不是只加手续费。"),a("li",null,"出处：证监会公告〔2024〕8 号；沪深北证券交易所《程序化交易管理实施细则》（2025 年 7 月 7 日起施行）；2023 年 9 月交易所报告与管理通知。")],-1))])}const b=l(d,[["render",p]]);export{D as __pageData,b as default};
